using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class PoliceResolutionTests
    {
        static TrafficTicket Ticket(string id="stop",bool serious=false)=>new TrafficTicket{Id=id,Street="Alta",Plate="RP123",Model=123,Lines=new System.Collections.Generic.List<TrafficLine>{new TrafficLine{Code=serious?TrafficOffence.AimingWeapon:TrafficOffence.NoSeatbelt,Amount=serious?350:150}}};
        static WalletData Start(bool bolo=true,bool serious=false)
        {var w=new WalletData{Bank=10000,Cash=42};Assert.True(TrafficTransactions.Configure(w,true,()=>{},out _));Assert.True(PoliceResolutionTransactions.Configure(w,true,bolo,()=>{}));Assert.True(TrafficTransactions.Begin(w,Ticket("stop",serious),()=>{},out _));return w;}
        [Theory] [InlineData(75,112)] [InlineData(100,150)] [InlineData(150,225)] [InlineData(350,525)] [InlineData(-1,0)]
        public void PriceMatchesReferenceRounding(int total,int expected)=>Assert.Equal(expected,PoliceResolutionRules.Price(total));
        [Theory] [InlineData(150,false,6000)] [InlineData(350,false,4500)] [InlineData(150,true,1500)] [InlineData(350,true,1125)]
        public void ReferenceRiskThresholds(int total,bool serious,int expected)=>Assert.Equal(expected,PoliceResolutionRules.Chance(total,serious));
        [Fact] public void AcceptedBribeSettlesOnlyCurrentTicketAndDebitsOnce(){var w=Start();Assert.True(PoliceResolutionTransactions.Bribe(w,"stop",0,0,()=>{},out bool changed));Assert.True(changed);Assert.Equal(9775,w.Bank);Assert.Equal(42,w.Cash);Assert.Null(w.Traffic.Pending);Assert.True(w.Traffic.Valid);var t=w.Traffic.Tickets.Single();Assert.True(t.Bribe.Accepted);Assert.False(t.Paid);Assert.Equal(0,w.Traffic.Collected);Assert.True(TrafficTransactions.Pay(w,"stop",()=>throw new Exception(),out changed));Assert.False(changed);Assert.True(PoliceResolutionTransactions.Bribe(w,"stop",9999,0,()=>throw new Exception(),out changed));Assert.False(changed);Assert.Equal(9775,w.Bank);}
        [Theory] [InlineData(5999,true)] [InlineData(6000,false)]
        public void ChanceBoundaryRecordedExactly(int roll,bool accepted){var w=Start();Assert.True(PoliceResolutionTransactions.Bribe(w,"stop",roll,0,()=>{},out _));Assert.Equal(accepted,w.Traffic.Tickets[0].Bribe.Accepted);Assert.Equal(accepted?9775:10000,w.Bank);}
        [Fact] public void RejectionPreservesFineAndCreatesPlateScopedBolo(){var w=Start();Assert.True(PoliceResolutionTransactions.Bribe(w,"stop",9999,0,()=>{},out _));Assert.Equal(10000,w.Bank);Assert.Equal("evaded",w.Traffic.Tickets[0].Outcome);Assert.True(PoliceResolutionRules.Bolo(w.Traffic,123," rp123 "));Assert.False(PoliceResolutionRules.Bolo(w.Traffic,123,"OTHER"));Assert.False(PoliceResolutionRules.Bolo(w.Traffic,124,"RP123"));Assert.False(PoliceResolutionTransactions.ClearBolo(w,123,"RP123",()=>{}));Assert.True(TrafficTransactions.Pay(w,"stop",()=>{},out _));Assert.Equal(9850,w.Bank);Assert.True(PoliceResolutionTransactions.ClearBolo(w,123,"RP123",()=>{}));Assert.False(w.Traffic.Bolos[0].Active);Assert.True(PoliceResolutionTransactions.ClearBolo(w,123,"RP123",()=>throw new Exception()));}
        [Fact] public void LegacyPreferencesDoNotActivateAnything(){var b=new TrafficData();Assert.False(b.BribesEnabled);Assert.False(b.BoloEnabled);Assert.Null(b.Bolos);var w=Start(false);Assert.True(TrafficTransactions.Finish(w,"stop","evaded",()=>{},out _));Assert.Null(w.Traffic.Bolos);}
        [Fact] public void EscapeAddsBoloWithoutChangingOldTicketAmount(){var w=Start();Assert.True(TrafficTransactions.Finish(w,"stop","evaded",()=>{},out _));Assert.Single(w.Traffic.Bolos);Assert.Equal(150,w.Traffic.Tickets[0].Total);Assert.True(TrafficTransactions.Finish(w,"stop","evaded",()=>throw new Exception(),out _));Assert.Single(w.Traffic.Bolos);}
        [Fact] public void InterruptionAndServiceDoNotCreateBolo(){foreach(string outcome in new[]{"served","interrupted"}){var w=Start();Assert.True(TrafficTransactions.Finish(w,"stop",outcome,()=>{},out _));Assert.Null(w.Traffic.Bolos);}}
        [Fact] public void StopPreferencesCannotChangeWhilePending(){var w=Start();Assert.False(PoliceResolutionTransactions.Configure(w,false,false,()=>throw new Exception()));Assert.True(w.Traffic.BribesEnabled);}
        [Theory] [InlineData(-1)] [InlineData(10000)]
        public void InvalidRollDoesNothing(int roll){var w=Start();string before=JsonConvert.SerializeObject(w);Assert.False(PoliceResolutionTransactions.Bribe(w,"stop",roll,0,()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Fact] public void DisabledInsufficientAndRemoteIdsCannotBribe(){var w=Start();w.Bank=224;Assert.False(PoliceResolutionTransactions.Bribe(w,"stop",0,0,()=>throw new Exception(),out _));Assert.Null(w.Traffic.Tickets[0].Bribe);w.Bank=10000;w.Traffic.BribesEnabled=false;Assert.False(PoliceResolutionTransactions.Bribe(w,"stop",0,0,()=>{},out _));w.Traffic.BribesEnabled=true;Assert.False(PoliceResolutionTransactions.Bribe(w,"other",0,0,()=>{},out _));}
        [Fact] public void NativeRequestIsOptInAndNeverPartOfReplay(){var w=Start();Assert.False(PoliceResolutionTransactions.Bribe(w,"stop",9999,2,()=>{},out _));w.Traffic.PursuitEnabled=true;w.Traffic.Tickets[0].Pursuit=new TrafficPursuitOptions();Assert.True(PoliceResolutionTransactions.Bribe(w,"stop",9999,2,()=>{},out bool changed));Assert.True(changed);Assert.Equal(2,w.Traffic.Tickets[0].Bribe.NativeStars);var reload=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.True(reload.Traffic.Valid);Assert.True(PoliceResolutionTransactions.Bribe(reload,"stop",9999,2,()=>throw new Exception(),out changed));Assert.False(changed);}
        [Fact] public void BankAndBookRollbackWhenBribeSaveFails(){var w=Start();string before=JsonConvert.SerializeObject(w);Assert.Throws<InvalidOperationException>(()=>PoliceResolutionTransactions.Bribe(w,"stop",0,0,()=>throw new InvalidOperationException(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));Assert.Throws<InvalidOperationException>(()=>PoliceResolutionTransactions.Bribe(w,"stop",9999,0,()=>throw new InvalidOperationException(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Fact] public void BoloClearRollbackRetainsRecord(){var w=Start();TrafficTransactions.Finish(w,"stop","evaded",()=>{},out _);TrafficTransactions.Pay(w,"stop",()=>{},out _);string before=JsonConvert.SerializeObject(w);Assert.Throws<InvalidOperationException>(()=>PoliceResolutionTransactions.ClearBolo(w,123,"RP123",()=>throw new InvalidOperationException()));Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Fact] public void ConfigurationRollbackDoesNotActivateOptions(){var w=new WalletData();Assert.Throws<InvalidOperationException>(()=>PoliceResolutionTransactions.Configure(w,true,true,()=>throw new InvalidOperationException()));Assert.Null(w.Traffic);}
        [Fact] public void SeriousBoloSnapshotLowersAcceptanceChance(){var w=Start();w.Traffic.Tickets[0].BoloAtStop=true;Assert.True(PoliceResolutionTransactions.Bribe(w,"stop",1500,0,()=>{},out _));Assert.False(w.Traffic.Tickets[0].Bribe.Accepted);Assert.Equal(1500,w.Traffic.Tickets[0].Bribe.Chance);}
        [Fact] public void UnknownFieldsSurviveAcceptedBribe(){var w=Start();w.Traffic.Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"Future",42}};PoliceResolutionTransactions.Bribe(w,"stop",0,0,()=>{},out _);Assert.Equal(42,(int)w.Traffic.Extra["Future"]);}
        [Theory] [InlineData("g_m_y_famca_01","g_m_y_ballaeast_01","g_m_y_famca_01")] [InlineData(null,"g_m_y_ballaeast_01","g_m_y_ballaeast_01")] [InlineData("",null,null)] [InlineData("bad path/", "g_m_y_ballaeast_01",null)]
        public void CoLeaderOnlyReplacesMissingLeader(string leader,string co,string expected){var g=new GangDefinition{LeaderModel=leader};if(co!=null)g.Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"CoLeaderModel",co}};Assert.Equal(expected,GangPresenceRules.ContactModel(g));}
        [Fact] public void CoLeaderPlansContactWithoutMutatingLegacyDefinition(){var g=new GangDefinition{Name="Gang",HQX=20,HQY=30,HQZ=40,Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"CoLeaderModel","g_m_y_famca_01"},{"Future",42}}};string before=JsonConvert.SerializeObject(g);var p=GangPresenceRules.Plan(g,6).Single();Assert.True(p.Leader);Assert.Equal(21.5f,p.Spot.X);Assert.Equal("g_m_y_famca_01",p.Model);Assert.Equal(before,JsonConvert.SerializeObject(g));}
        [Fact] public void MissingAndMalformedCoLeaderDoNotInventNpc(){var g=new GangDefinition{Name="Gang",HQX=20,HQY=30,HQZ=40};Assert.Empty(GangPresenceRules.Plan(g,6));g.Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"CoLeaderModel",42}};Assert.Null(GangPresenceRules.ContactModel(g));}
    }
}
